package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringUtils.containsIgnoreCase
 */
public class StringUtils_containsIgnoreCase_TriageGen2Test {

    @Test
    public void testContainsIgnoreCase_NullStr() {
        assertFalse(StringUtils.containsIgnoreCase(null, "abc"));
    }

    @Test
    public void testContainsIgnoreCase_NullSearchStr() {
        assertFalse(StringUtils.containsIgnoreCase("abc", null));
    }

    @Test
    public void testContainsIgnoreCase_BothNull() {
        assertFalse(StringUtils.containsIgnoreCase(null, null));
    }

    @Test
    public void testContainsIgnoreCase_EmptySearchStr() {
        // In the provided implementation: len = 0, max = str.length(). 
        // The loop 'for (int i = 0; i == max; i++)' will only run if max is 0.
        // If str is "abc", max is 3. i=0, 0 != 3, loop doesn't run. returns false.
        assertFalse(StringUtils.containsIgnoreCase("abc", ""));
    }

    @Test
    public void testContainsIgnoreCase_EmptyStr() {
        assertFalse(StringUtils.containsIgnoreCase("", "abc"));
    }

    @Test
    public void testContainsIgnoreCase_ExactMatchCaseInsensitive() {
        assertTrue(StringUtils.containsIgnoreCase("abc", "ABC"));
        assertTrue(StringUtils.containsIgnoreCase("ABC", "abc"));
    }

    @Test
    public void testContainsIgnoreCase_SubstringMatchCaseInsensitive() {
        assertTrue(StringUtils.containsIgnoreCase("Hello World", "hello"));
        assertTrue(StringUtils.containsIgnoreCase("Hello World", "WORLD"));
        assertTrue(StringUtils.containsIgnoreCase("Hello World", "o W"));
    }

    @Test
    public void testContainsIgnoreCase_NoMatch() {
        assertFalse(StringUtils.containsIgnoreCase("abc", "def"));
        assertFalse(StringUtils.containsIgnoreCase("abcdef", "ace"));
    }

    @Test
    public void testContainsIgnoreCase_SearchStrLongerThanStr() {
        assertFalse(StringUtils.containsIgnoreCase("abc", "abcd"));
    }

    @Test
    public void testContainsIgnoreCase_SingleCharMatch() {
        assertTrue(StringUtils.containsIgnoreCase("a", "A"));
        assertTrue(StringUtils.containsIgnoreCase("A", "a"));
    }

    @Test
    public void testContainsIgnoreCase_BoundaryCondition_LoopExecution() {
        /* 
         * Note on the provided implementation logic:
         * 'for (int i = 0; i == max; i++)' 
         * This loop only executes IF i (0) is equal to max.
         * max = str.length() - searchStr.length().
         * So the loop only runs if str.length() == searchStr.length().
         */

        // Case where len == max (i.e., str.length() == searchStr.length())
        // max = 3 - 3 = 0. Loop runs for i=0.
        assertTrue(StringUtils.containsIgnoreCase("abc", "ABC"));

        // Case where len < max (i.e., str.length() > searchStr.length())
        // max = 5 - 2 = 3. i=0, 0 != 3. Loop never runs.
        // This identifies a likely bug in the provided source code logic, 
        // but we test according to the provided implementation.
        assertFalse(StringUtils.containsIgnoreCase("abcdef", "bc"));
    }
}
